const btnClass='btn btn-primary';
const summarizeReadWarnings=(warnings:ReadWarning[])=>{
 const unique=Array.from(new Map(warnings.map(item=>[item.method+':'+item.diagnostic.kind,item])).values());
 return unique.slice(0,4).map(item=>{
  const d=item.diagnostic;const source=d.httpStatus?`HTTP ${d.httpStatus}`:d.code!==undefined?`code ${d.code}`:sentenceCase(d.kind);
  const attempts=d.attempts>1?` after ${d.attempts} attempts`:'';
  return `${d.contractMethod} ${source}${attempts}: ${item.cached?'last confirmed data is shown.':'data is unavailable.'}`;
 }).join(' ')+(unique.length>4?' More read diagnostics are available in the browser session log.':'');
};
const readAvailability=async <T,>(method:string,args:unknown[],warnings:ReadWarning[],force:boolean,onWarning?:()=>void):Promise<T>=>{
 try{
  const result=await readDetailed(method,args,{force});
  if(result.warning){warnings.push({method,diagnostic:result.warning,cached:true});onWarning?.()}
  return result.value as T;
 }catch(error){
  const diagnostic=error instanceof ReadRequestError?error.diagnostic:diagnoseReadError(method,error,1);
  warnings.push({method,diagnostic,cached:false});onWarning?.();
  throw error;
 }
};
const optionalRead=async <T,>(method:string,args:unknown[],warnings:ReadWarning[],force:boolean,onWarning?:()=>void):Promise<T|undefined>=>{
 try{return await readAvailability<T>(method,args,warnings,force,onWarning)}catch{return undefined}
};
function TransactionStatus({text}:{text:string}){
 const match=text.match(/0x[a-fA-F0-9]{64}/);
 if(!match)return <span>{text}</span>;
 const [before,after]=text.split(match[0]);
 return <span>{before}<a className="mono tx-link" href={transactionExplorerUrl(match[0])} target="_blank" rel="noreferrer">{match[0]}</a>{after}</span>;
}
